def test_mgga_xc_lp90_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_lp90", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.907874544693962e+00, -5.392538448951157e+00, -4.972596230696850e+00, -4.596040929916206e+00, -4.220642207375387e+00, -3.811772855149898e+00, -3.343606975969724e+00, -2.804328854403675e+00, -2.204524129807077e+00, -1.579678930802093e+00, -9.577694557863630e-01, -6.408225648400971e-01, -6.214820996200610e-01, -5.055525016208806e-01, -3.504232042465834e-01, -2.097349140428687e-01, -1.207214615037891e-01, -1.102436561209947e-01, -2.853197320386396e-01, -1.727346778295005e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


